import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});
 await call('Page.navigate',{url:'http://127.0.0.1:3000'});
 const output='docs/diario-ia/qa-resultados/titulo-enquadramento';await mkdir(output,{recursive:true});
 const results=[];
 for(const [width,height] of [[1920,1080],[1366,768],[1024,768],[390,844],[844,390],[320,568],[390,844]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:width<900});
  let ready=false;for(let i=0;i<100;i++){if(await evaluate(`document.querySelector('#title-scene')?.width>=1080`)){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready,'Cena carregada');
  await evaluate('document.fonts.ready.then(()=>true)');await new Promise(r=>setTimeout(r,200));
  const metrics=await evaluate(`(async()=>{const {titleSceneFrame,TITLE_SCENE_LAYOUT:l}=await import('/src/js/ui/TitleScene.js');const c=document.querySelector('#title-scene'),f=titleSceneFrame(c.width,c.height),r=document.querySelector('.title-menu').getBoundingClientRect();const buttons=[...document.querySelectorAll('.title-actions button')].map(b=>{const q=b.getBoundingClientRect();return {x:q.x,y:q.y,width:q.width,height:q.height};});return {canvas:[c.width,c.height],frame:f,chair:l,menu:{x:r.x,y:r.y,width:r.width,height:r.height},buttons};})()`);
  assert.ok(metrics.menu.x>=0&&metrics.menu.x+metrics.menu.width<=width+1,'Menu enquadrado');
  for(const b of metrics.buttons)assert.ok(b.y>=0&&b.y+b.height<=height+1,'Ações acessíveis');
  const f=metrics.frame;assert.ok(f.x<=.01&&f.y<=.01&&f.x+1920*f.scale>=metrics.canvas[0]-.01&&f.y+1080*f.scale>=metrics.canvas[1]-.01,'Fundo cobre tela sem lacunas');
  assert.deepEqual(metrics.chair,results[0]?.chair??metrics.chair,'Poltrona conserva coordenadas e escala no quarto');
  results.push({width,height,...metrics});const shot=await call('Page.captureScreenshot',{format:'png'});const bytes=Buffer.from(shot.result.data,'base64');await writeFile(output+'/'+width+'x'+height+'.png',bytes);await writeFile('/tmp/legendgirl-titulo-'+width+'x'+height+'.png',bytes);
 }
 console.log(JSON.stringify(results,null,2));console.log('APROVADO: enquadramento comum do quarto, poltrona fixa, menu acessível e rotação/resize.');
} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
